SnapshotKind = Literal["assistant.approval", "assistant.permission", "assistant.question", "assistant.reminder", "assistant.unavailable"]


def snapshot(
    firing: Sequence[Entry],
    *,
    kinds: Sequence[SnapshotKind] | None = None,
    stale_after: str | None = None,
) -> Sent:
    """Everything of `assistant` that is firing now: whatever was open and isn't listed resolves."""
    return _beacon.snapshot(SOURCE, firing, kinds=kinds, stale_after=stale_after)


def unobserved(reason: str, *, stale_after: str | None = None) -> Sent:
    """`assistant` couldn't see what it watches: its alerts are muted until its next snapshot."""
    return _beacon.snapshot(SOURCE, [], stale_after=stale_after, reason=reason)
